local CollarOfEstate = {}
local PRODUCTS = {
    iron_chain_collar = { name = "Železna verižna ogrlica", ironCost = 2, time = 5, cost = 130, prestige = 3, happiness = 1, description = "Železna ogrlica za nižje uradnike." },
    silver_link_collar = { name = "Srebrnoverižna ogrlica", silverCost = 2, ironCost = 1, time = 7, cost = 340, prestige = 8, happiness = 2, description = "Srebrna ogrlica za dvorne uradnike." },
    gilded_chancellor_collar = { name = "Pozlačena kanclerska ogrlica", goldCost = 1, silverCost = 2, ironCost = 1, time = 11, cost = 780, prestige = 16, happiness = 3, description = "Pozlačena ogrlica za kanclerje." },
    jewel_set_estate_collar = { name = "Draguljasta dvorna ogrlica", goldCost = 2, silverCost = 2, jewelCost = 1, time = 15, cost = 1750, prestige = 28, happiness = 4, description = "Ogrlica z dragulji za visoke dvorjane." },
    pearl_link_state_collar = { name = "Bisernoverižna državna ogrlica", goldCost = 2, silverCost = 2, jewelCost = 1, pearlCost = 1, time = 19, cost = 3800, prestige = 48, happiness = 6, description = "Biserna državna ogrlica za suverene časti." },
    royal_sovereign_collar = { name = "Kraljevska suverena ogrlica", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, time = 26, cost = 8400, prestige = 86, happiness = 12, description = "Suverena ogrlica z biseri za kronanje." },
}
local BUILDINGS = {
    chain_workshop = { name = "Verižna delavnica", cost = { gold = 320, wood = 140, stone = 120, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    estate_jewelers_house = { name = "Državna draginarska hiša", cost = { gold = 1100, wood = 280, stone = 240, silver = 6, iron = 6 }, upkeep = 25, qualityBonus = 18 },
    master_collar_atelier = { name = "Mojstrski ovratniški atelje", cost = { gold = 2900, wood = 360, stone = 480, silver = 32, gold = 6 }, upkeep = 70, qualityBonus = 30 },
    sovereign_estate_palace = { name = "Suverena državna palača", cost = { gold = 12500, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 250, qualityBonus = 55, prestigeBonus = 50 },
}
CollarOfEstate.ironStock = 14; CollarOfEstate.silverStock = 10; CollarOfEstate.goldStock = 6; CollarOfEstate.jewelStock = 4; CollarOfEstate.pearlStock = 4
CollarOfEstate.productStock = {}; CollarOfEstate.buildings = {}; CollarOfEstate.maker = nil; CollarOfEstate.activeMaking = {}; CollarOfEstate.totalProducts = 0; CollarOfEstate.dayTimer = 0
function CollarOfEstate.init() CollarOfEstate.ironStock=14; CollarOfEstate.silverStock=10; CollarOfEstate.goldStock=6; CollarOfEstate.jewelStock=4; CollarOfEstate.pearlStock=4; CollarOfEstate.productStock={}; CollarOfEstate.buildings={}; CollarOfEstate.maker=nil; CollarOfEstate.activeMaking={}; CollarOfEstate.totalProducts=0; CollarOfEstate.dayTimer=0; print("[CollarOfEstate] Royal Collar of Estate System initialized (6 products, 4 buildings)") end
function CollarOfEstate.hireMaker(n,s) s=s or math.random(55,90); local c=600+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CollarOfEstate.maker={name=n or ("Ovratničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ovratničar najet: %s (spretnost: %d)",CollarOfEstate.maker.name,s),"success") end; return true end
function CollarOfEstate.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CollarOfEstate.build(id) local ok,e=CollarOfEstate.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CollarOfEstate.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CollarOfEstate.getQualityBonus() local b=0; for _,bd in ipairs(CollarOfEstate.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CollarOfEstate.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CollarOfEstate.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and CollarOfEstate.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CollarOfEstate.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CollarOfEstate.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CollarOfEstate.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CollarOfEstate.buildings==0 then return false,"Potrebna verižna delavnica" end; if not CollarOfEstate.maker then return false,"Potreben ovratničar" end; return true end
function CollarOfEstate.make(pt,qty) qty=qty or 1; local ok,e=CollarOfEstate.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CollarOfEstate.ironStock=CollarOfEstate.ironStock-d.ironCost*qty end; if d.silverCost then CollarOfEstate.silverStock=CollarOfEstate.silverStock-d.silverCost*qty end; if d.goldCost then CollarOfEstate.goldStock=CollarOfEstate.goldStock-d.goldCost*qty end; if d.jewelCost then CollarOfEstate.jewelStock=CollarOfEstate.jewelStock-d.jewelCost*qty end; if d.pearlCost then CollarOfEstate.pearlStock=CollarOfEstate.pearlStock-d.pearlCost*qty end; local t=d.time; if CollarOfEstate.maker then t=math.max(1,t-math.floor(CollarOfEstate.maker.skill/13)) end; table.insert(CollarOfEstate.activeMaking,{id="collar_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CollarOfEstate.completeMaking(m) local q=1.0+(CollarOfEstate.getQualityBonus()/100); if CollarOfEstate.maker then q=q+(CollarOfEstate.maker.skill/140) end; q=math.min(2.5,q); CollarOfEstate.productStock[m.productType]=(CollarOfEstate.productStock[m.productType] or 0)+m.quantity; CollarOfEstate.totalProducts=CollarOfEstate.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CollarOfEstate.maker then CollarOfEstate.maker.itemsMade=CollarOfEstate.maker.itemsMade+m.quantity; if math.random()<0.25 then CollarOfEstate.maker.skill=math.min(100,CollarOfEstate.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ogrlica izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"collar.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CollarOfEstate.update(dt) if not _G.state then return end; CollarOfEstate.dayTimer=CollarOfEstate.dayTimer+dt; if CollarOfEstate.dayTimer>=30 then CollarOfEstate.dayTimer=0; for i=#CollarOfEstate.activeMaking,1,-1 do local m=CollarOfEstate.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CollarOfEstate.completeMaking(m); table.remove(CollarOfEstate.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CollarOfEstate.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CollarOfEstate.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CollarOfEstate.getStats() return {ironStock=CollarOfEstate.ironStock,silverStock=CollarOfEstate.silverStock,goldStock=CollarOfEstate.goldStock,jewelStock=CollarOfEstate.jewelStock,pearlStock=CollarOfEstate.pearlStock,productStock=CollarOfEstate.productStock,numBuildings=#CollarOfEstate.buildings,hasMaker=CollarOfEstate.maker~=nil,makerName=CollarOfEstate.maker and CollarOfEstate.maker.name or "—",makerSkill=CollarOfEstate.maker and CollarOfEstate.maker.skill or 0,activeMaking=#CollarOfEstate.activeMaking,totalProducts=CollarOfEstate.totalProducts} end
return CollarOfEstate
